from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(70))

def power(base, n):
    if n == 0:
        return 1
    half = power(base, n // 2)
    return half * half if n % 2 == 0 else half * half * base
print(power(2, 10))

